# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_component_add() {
    nsh component list 2>&1 | gawk '$2 == "not" && $3 == "installed" { print $1 }'
}

_choice_component_remove() {
    nsh component list 2>&1 | gawk '$2 == "installed" { print $1 }'
}

_choice_nshm() {
    local manifest
    manifest="$(_argc_util_path_search_parent nsh.json)"
    [[ -n $manifest ]] || return 0
    jq -b -r '(.dependencies // {}) | keys[]' "$manifest" 2>/dev/null
}

_choice_publish_android_track() {
    printf '%s\n' internal alpha beta production
}
